'use client';

import { useId, useState } from 'react';
import type { KeyboardEvent } from 'react';
import { Tab } from './components/ui/tab';

const tabs = [
  { value: 'courses', label: '내 강의', content: '수강 중인 강의예요.' },
  { value: 'saved', label: '저장한 강의', content: '저장한 강의예요.' },
];

export default function Example() {
  const prefix = useId();
  const [selected, setSelected] = useState('courses');

  // Tab 자체가 제공하지 않는 그룹의 이동·단일 선택을 소비 앱에서 연결해요.
  const onGroupKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const current = tabs.findIndex(tab => tab.value === selected);
    const nextIndex = event.key === 'ArrowRight' ? (current + 1) % tabs.length
      : event.key === 'ArrowLeft' ? (current - 1 + tabs.length) % tabs.length
      : event.key === 'Home' ? 0
      : event.key === 'End' ? tabs.length - 1 : undefined;
    if (nextIndex === undefined) return;
    const next = tabs[nextIndex];
    if (!next) return;
    event.preventDefault();
    setSelected(next.value);
    event.currentTarget.querySelectorAll<HTMLButtonElement>('[role="tab"]')[nextIndex]?.focus();
  };

  return (
    <>
      <div role="tablist" aria-label="강의 보기" onKeyDown={onGroupKeyDown}>
        {tabs.map(tab => (
          <Tab
            key={tab.value}
            id={prefix + '-tab-' + tab.value}
            aria-controls={prefix + '-panel-' + tab.value}
            label={tab.label}
            active={selected === tab.value}
            tabIndex={selected === tab.value ? 0 : -1}
            onActiveChange={nextActive => { if (nextActive) setSelected(tab.value); }}
          />
        ))}
      </div>
      {tabs.map(tab => (
        <div
          key={tab.value}
          id={prefix + '-panel-' + tab.value}
          role="tabpanel"
          aria-labelledby={prefix + '-tab-' + tab.value}
          hidden={selected !== tab.value}
          tabIndex={0}
        >
          {tab.content}
        </div>
      ))}
    </>
  );
}
